module tb;

  // ------------------------------------------------------------
  // Clock and reset
  // ------------------------------------------------------------
  logic        clk = 0;
  always #5 clk = ~clk;   // 100 MHz clock (10 time‑units period)

  logic        rst = 1'b0;
  initial begin
    rst = 1'b1;
    #20;
    rst = 1'b0;
    #20;
  end

  // ------------------------------------------------------------
  // UART interface signals (DUT ports)
  // ------------------------------------------------------------
  logic        rxd = 1'b1;                     // UART receiver input
  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid;
  logic        m_axis_tready;                  // driven by testbench
  logic [15:0] prescale = 16'd5;               // default configuration

  // ------------------------------------------------------------
  // DUT instantiation (default parameters)
  // ------------------------------------------------------------
  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk           (clk),
    .rst           (rst),
    .m_axis_tdata  (m_axis_tdata),
    .m_axis_tvalid (m_axis_tvalid),
    .m_axis_tready (m_axis_tready),
    .rxd           (rxd),
    .busy          (),      // unused
    .overrun_error (),      // unused
    .frame_error   (),      // unused
    .prescale      (prescale)
  );

  // ------------------------------------------------------------
  // Helper tasks
  // ------------------------------------------------------------
  task automatic wait_cycles(input int n);
    repeat (n) @(posedge clk);
  endtask

  // Send one byte on rxd (LSB‑first, 8N1)
  task automatic send_byte(input byte unsigned b);
    int bit_clks;
    bit_clks = prescale * 8;

    // start bit
    rxd = 0;
    wait_cycles(bit_clks);

    // data bits
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      wait_cycles(bit_clks);
    end

    // stop bit
    rxd = 1;
    wait_cycles(bit_clks);
  endtask

  // ------------------------------------------------------------
  // Main stimulus
  // ------------------------------------------------------------
  initial begin
    // Initialise AXI‑Stream ready low
    m_axis_tready = 1'b0;

    // --------------------------------------------------------
    // 1) Receive first word (8'h3C) and stall it
    // --------------------------------------------------------
    // Feed a frame containing 8'h3C (binary 0011 1100)
    send_byte(8'h3C);

    // Wait until the DUT asserts m_axis_tvalid (word ready)
    wait (m_axis_tvalid);

    // Keep ready low to create back‑pressure
    // Hold for a while, then accept the word
    repeat (40) @(posedge clk);
    m_axis_tready = 1'b1;          // handshake – word is accepted
    @(posedge clk);
    m_axis_tready = 1'b0;          // release ready again

    // Wait for the handshake to complete (m_axis_tvalid drops)
    wait (!m_axis_tvalid);

    // --------------------------------------------------------
    // 2) Send second word (8'hA5) – this should trigger the cover
    // --------------------------------------------------------
    send_byte(8'hA5);

    // Wait for the second word to be presented
    wait (m_axis_tvalid);

    // Keep ready low so the word can be captured completely
    // Wait until the DUT de‑asserts m_axis_tvalid
    wait (!m_axis_tvalid);

    // --------------------------------------------------------
    // 3) End of simulation
    // --------------------------------------------------------
    #1000;
    $finish;
  end

endmodule

