module tb;

  localparam int CLK_PERIOD = 8;
  localparam logic [15:0] PRESCALE = 16'd5;

  logic        clk = 1'b0;
  logic        rst = 1'b0;
  logic [7:0]  s_axis_tdata = '0;
  logic        s_axis_tvalid = 1'b0;
  logic        m_axis_tready = 1'b0;
  logic        rxd = 1'b1;
  logic [15:0] prescale = PRESCALE;
  wire  [7:0]  m_axis_tdata;
  wire         m_axis_tvalid;
  wire         s_axis_tready;
  wire         txd;
  wire         tx_busy;
  wire         rx_busy;
  wire         rx_overrun_error;
  wire         rx_frame_error;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart dut (
    .clk(clk), .rst(rst),
    .s_axis_tdata(s_axis_tdata), .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata(m_axis_tdata), .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .txd(txd),
    .tx_busy(tx_busy), .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error), .rx_frame_error(rx_frame_error),
    .prescale(prescale)
  );

  // All driving/sampling on the falling edge so DUT inputs are stable at
  // every rising edge.
  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1'b1; wait_clks(4);
    rst = 1'b0; wait_clks(4);
  endtask

  task automatic wait_valid(input logic v);
    do begin
      @(negedge clk);
    end while (m_axis_tvalid !== v);
  endtask

  // 8N1 frame on rxd, LSB first, each bit prescale*8 clocks.
  task automatic uart_send_byte(input byte unsigned b);
    int bit_clks = int'(prescale) * 8;
    rxd = 1'b0;                   wait_clks(bit_clks);  // start
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];                 wait_clks(bit_clks);
    end
    rxd = 1'b1;                   wait_clks(bit_clks);  // stop
  endtask

  // A short low pulse on rxd while the receiver is idle. The receiver latches
  // a start bit, but by the mid-start-bit sample (prescale_reg==0, bit_cnt==10)
  // rxd_reg is high, so the start is rejected. The pulse (12 clocks) is long
  // enough to latch the start but short enough that the mid-bit sample sees
  // rxd high (it must be high at the 19th posedge after the first low).
  task automatic do_false_start();
    rxd = 1'b0;
    wait_clks(12);
    rxd = 1'b1;
    wait_clks(30);
  endtask

  initial begin
    do_reset();
    m_axis_tready = 1'b0;
    s_axis_tvalid = 1'b0;

    // 1. Receive 0x3C with the sink stalled -> pending word 8'h3C.
    uart_send_byte(8'h3C);
    wait_valid(1'b1);
    wait_clks(4);

    // 2. Rejected (false) start bit while 0x3C is still pending and stalled.
    //    m_axis_tvalid stays high with 8'h3C, overrun_error stays low.
    do_false_start();

    // 3. Handshake the pending 0x3C (sink becomes ready).
    m_axis_tready = 1'b1;
    wait_valid(1'b0);
    wait_clks(4);

    // 4. Receive a fresh, complete frame 0xA5 (no overrun).
    uart_send_byte(8'hA5);
    wait_valid(1'b1);
    wait_clks(4);

    $display("PASS tb R28");
    $finish;
  end

  initial begin
    #100ms;
    $fatal(1, "timeout");
  end

endmodule
